function egfr(scr, age, sex){
  scr=+scr; age=+age; sex=(sex||'male').toLowerCase();
  if(!(scr>0)||!(age>=0)) return {error:'肌酐(scr)与年龄须为有效正数'};
  var k = sex==='female'?0.7:0.9;
  var a = sex==='female'?-0.241:-0.302;
  var min=Math.min(scr/k,1), max=Math.max(scr/k,1);
  var g = 142 * Math.pow(min,a) * Math.pow(max,-1.200) * Math.pow(0.9938, age);
  if(sex==='female') g*=1.012;
  g=Math.round(g*10)/10;
  var stage;
  if(g>=90) stage='G1（正常或偏高）';
  else if(g>=60) stage='G2（轻度下降）';
  else if(g>=45) stage='G3a（轻-中度下降）';
  else if(g>=30) stage='G3b（中-重度下降）';
  else if(g>=15) stage='G4（重度下降）';
  else stage='G5（肾衰竭）';
  return {egfr:g, stage:stage};
}
var EXPORTS={egfr:egfr};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.EgfrForgePure = EXPORTS; }
